CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_MARKET_SETTLEMENT_MONTH_TYPE_ACCOUNT_CODE
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_MARKET_SETTLEMENT at grain Date.FiscalYear, Date.MonthName, GLAccount.AccountCode, MarketSettlement.MarketType, Date.MonthNumber; covers 77.08% of weighted demand (3 clusters); est. 6,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.MONTH_NAME,
       g2.ACCOUNT_CODE,
       f.MARKET_TYPE,
       d1.MONTH_NUMBER,
       SUM(f.ENERGY_MWH) AS ENERGY_MWH,
       SUM(f.PRICE_MWH) AS PRICE_MWH_SUM,
       COUNT(f.PRICE_MWH) AS PRICE_MWH_COUNT,
       SUM(f.SETTLEMENT_AMOUNT) AS SETTLEMENT_AMOUNT,
       COUNT(*) AS MARKET_SETTLEMENT_COUNT
FROM CORE.FCT_MARKET_SETTLEMENT f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_GL_ACCOUNT g2 ON f.GL_ACCOUNT_ID = g2.GL_ACCOUNT_ID
GROUP BY ALL;

